{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret fejlfortolker udtalelsens indhold og retsvirkning. Det gør udtalelsen til en vurdering af erhvervsskade og varig formindskelse af arbejdsevnen, hvilket ikke fremgår af kilden. Det hævder, at Udbetaling Danmark er bundet af udtalelsen, hvis den er afgivet efter en 'saglig og mønstret vurdering'. Kilden og rubrikken siger det modsatte: udtalelsen er kun vejledende og ikke bindende. Dette er en væsentlig juridisk fejl."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Svaret nævner ikke de to kritiske elementer: hvor meget funktionsnedsættelsen påvirker evnen til at arbejde, og om funktionsevnen er så nedsat, at et studiejob ikke kan varetages. Det beskriver i stedet erhvervsrelateret skade og varig formindskelse af arbejdsevnen."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Svaret forsøger at besvare begge dele af spørgsmålet, men indholdet er forkert. Det indeholder generiske formuleringer om 'retlige krav og retningslinjer' og 'særlige omstændigheder'. Det besvarer ikke, hvad udtalelsen skal belyse, og giver et forkert svar på bindingsspørgsmålet."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke bedømmes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke bedømmes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer regler uden støtte i materialet: at udtalelsen kun kan belyse ret hvis der er en erhvervsskade, at udtalelsen skal være afgivet efter en 'saglig og mønstret vurdering', at Udbetaling Danmark er bundet under denne betingelse, og at der gælder en tvivlsregel om udtalelsens gyldighed."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Den påkrævede kvalifikation, at udtalelsen er vejledende og ikke bindende for Udbetaling Danmark, mangler. Svaret hævder det modsatte som hovedregel. Det nævner heller ikke, at udtalelsen udarbejdes på sagens dokumentation uden undersøgelse."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret er internt uklart. Det siger først, at Udbetaling Danmark er bundet og skal følge udtalelsen. Derefter siger det, at Udbetaling Danmark kan foretage en selvstændig vurdering ved tvivl. Det udhuler bindingen uden en klar regel, så konklusionen følger ikke klart af trinene."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret bruger 'er bundet' og 'skal tage ... til følge', hvor kilden siger, at udtalelsen er vejledende og ikke bindende. Det gør en vejledende udtalelse til en bindende, og modaliteten gengives forkert."}
  },
  "xhaile_coverage": {
    "A68": {"label": "no", "reason": "Svaret dækker ikke punktets kerne. Det nævner ikke vurderingen af, hvor meget funktionsnedsættelsen påvirker evnen til at arbejde, eller om funktionsevnen er så nedsat, at et studiejob ikke kan varetages. Det nævner ikke, at udtalelsen er vejledende, at den udarbejdes på foreliggende dokumentation uden undersøgelse, eller at styrelsen betaler udgifterne. Det omtaler erhvervsskade og binding, som ikke findes i punktet."}
  },
  "overall_notes": "Svaret er juridisk forkert på de væsentligste punkter. Det opfinder erhvervsskadekriterier og en bindingsregel, mangler de kritiske elementer (arbejdsevne og studiejob) og angiver ingen kilder. Derfor er C04 not_met, mens C05 og C06 er not_assessable."
}

